const FIX = {
'email address': 'Correo electrónico',
'tests': 'Tests',
'7-day full access': 'Acceso completo de 7 días',
'invalid email or password.': 'Correo electrónico o contraseña no válidos.',
'invalid email or password': 'Correo electrónico o contraseña no válidos',
'sign into your account': 'Inicia sesión'
};
const CONTACT = /^contact us$/i;
const NAVISH = /(^|::)(nav|menu|footer|header|metadata|meta)(::|$)|::title(::|$)/i;

const rows = [];
const changed = [];
for (const p of $input.all()) {
  const b = (p.json && p.json.body) || {};
  if (!Array.isArray(b.keys)) continue;
  for (const k of b.keys) {
    let en = '', es = '', sids = [];
    for (const tr of (k.translations || [])) {
      if (tr.language_iso === 'en') en = String(tr.translation === null ? '' : tr.translation);
      if (tr.language_iso === 'es') {
        es = String(tr.translation === null ? '' : tr.translation);
        for (const s of (tr.custom_translation_statuses || [])) { sids.push(s.status_id); }
      }
    }
    const kn = k.key_name;
    const name = (typeof kn === 'string') ? kn : ((kn && (kn.web || kn.other)) || '');
    const flat = en.trim().toLowerCase();
    let want = null;
    if (CONTACT.test(en.trim())) {
      want = NAVISH.test(name) ? 'Contacto' : 'Contáctanos';
    } else if (FIX[flat] !== undefined) {
      want = FIX[flat];
    }
    if (want === null) continue;
    if (es.trim() === want) continue;
    rows.push({ key_id: k.key_id, translations: [{ language_iso: 'es', translation: want, is_reviewed: false, is_fuzzy: false, custom_translation_status_ids: sids }] });
    changed.push({ key: name, en: en.slice(0, 40), from: es.slice(0, 50), to: want });
  }
}
const CHUNK = 150;
const out = [];
for (let i = 0; i < rows.length; i += CHUNK) {
  out.push({ json: { chunk: (i / CHUNK) + 1, total: rows.length, changed: changed, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/keys', body: { keys: rows.slice(i, i + CHUNK) } } });
}
if (!out.length) { out.push({ json: { chunk: 0, total: 0, changed: [], skip: true, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/keys', body: { keys: [] } } }); }
return out;

const plan = $('Build Corrections').first().json;
const wr = $('Write Fixes').all();
let ok = 0, updated = 0;
const errors = [];
for (const r of wr) {
  const j = r.json || {};
  const b = j.body || {};
  if (j.statusCode === 200 && Array.isArray(b.keys)) { ok++; updated += b.keys.length; }
  else if (j.statusCode) errors.push({ statusCode: j.statusCode, err: JSON.stringify(b).slice(0, 200) });
}
const g = $input.first().json || {};
const gb = g.body || {};
return [{ json: {
  planned: plan.total,
  keys_updated: updated,
  ok_requests: ok,
  write_errors: errors,
  changed: plan.changed,
  glossary_status: g.statusCode,
  glossary_response: JSON.stringify(gb).slice(0, 500)
} }];
